# Find columns where the "pattern color" (3) appears in ALL non-separator rows
# Non-separator rows are 0-3
all_rows_with_3 = []
for col in range(22):
    has_3_in_all = True
    for row in range(4):  # rows 0-3
        if input_grid[row][col] != 3:
            has_3_in_all = False
            break
    if has_3_in_all:
        all_rows_with_3.append(col)

print("Columns with 3 in all rows 0-3:", all_rows_with_3)

# Build output: 2 at all intersection columns, rest as original
output_grid = [[0]*22 for _ in range(5)]
for row in range(5):
    for col in range(22):
        output_grid[row][col] = input_grid[row][col]

# Overwrite intersection columns with 2
for row in range(5):
    for col in all_rows_with_3:
        output_grid[row][col] = 2

for row in output_grid:
    print(' '.join(map(str, row)))

